<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import ReportChart from '../components/ReportChart.vue'
import { get } from '../api/client'
import { useViewerStore } from '../stores/viewer'
import type { PreferenceReport } from '../types/viewer'
import DistributionBars from '../components/DistributionBars.vue'
import ViewingCard from '../components/ViewingCard.vue'
import ViewerReportPanel from '../components/ViewerReportPanel.vue'
import RecommendationsPanel from '../components/RecommendationsPanel.vue'
import { evidenceLink } from '../utils/libraryFilters'
const router=useRouter()
const viewer = useViewerStore()
const report = ref<PreferenceReport>(), source = ref<'COMMUNITY' | 'PERSONAL'>('COMMUNITY'), loading = ref(false), error = ref(''), sort = ref('frequency')
let controller: AbortController | undefined, version = 0
async function load() {
  controller?.abort(); controller = new AbortController(); const current = controller, currentVersion = ++version
  if (!viewer.state?.bound) { report.value = undefined; loading.value = false; return }
  loading.value = true; error.value = ''
  try { const result = await get<PreferenceReport>(`/viewer/preferences?tagSource=${source.value}&tagSort=${sort.value === 'rating' ? 'RATING' : 'FREQUENCY'}`, current.signal); if (version === currentVersion) report.value = result }
  catch(e) { if (!current.signal.aborted) error.value = e instanceof Error ? e.message : '偏好数据加载失败' }
  finally { if (version === currentVersion) loading.value = false }
}
const tags = computed(() => report.value?.tags || [])
const tagEvidence = (tag: string) => evidenceLink({ tag, tagSource: report.value?.tagSource || source.value })
const statusEvidence = (label: string) => evidenceLink({ status: ({ 想看: '1', 已看: '2', 在看: '3', 搁置: '4', 抛弃: '5' } as Record<string, string>)[label] || '' })
const years = computed(() => [...(report.value?.years || [])].sort((a,b)=>a.label==='未知'?1:b.label==='未知'?-1:a.label.localeCompare(b.label)))
watch([source, sort], load)
watch(() => `${viewer.state?.bound}|${viewer.state?.profile?.id}|${viewer.state?.lastSyncedAt}`, (next, previous) => { if (next.split('|')[1] !== previous?.split('|')[1]) report.value = undefined; load() }, { immediate: true })
onMounted(() => viewer.load())
onUnmounted(() => controller?.abort())
</script>
<template>
  <section class="preference-intro"><div><p class="eyebrow">YOUR TASTE / 观看偏好</p><h1>喜欢什么，<span>让片单告诉你。</span></h1><p>从已看作品、个人评分和标签中寻找线索。每个观察，都有数据可回看。</p></div><RouterLink to="/library" class="button">← 返回我的片单</RouterLink></section>
  <p v-if="viewer.error" class="feedback error" role="alert">{{ viewer.error }} <button @click="viewer.load">重试</button></p>
  <section v-if="!viewer.state?.bound && !viewer.loading" class="preference-empty"><span>◎</span><h2>先带上你的片单</h2><p>关联 Bangumi 并同步收藏后，这里会出现属于你的观看统计。</p><RouterLink to="/library" class="button primary">关联 Bangumi</RouterLink></section>
  <p v-if="viewer.state?.syncStatus === 'RUNNING'" class="feedback" role="status">片单正在同步，完成后自动更新统计；当前数字来自上次成功同步。</p>
  <p v-if="viewer.state?.truncated" class="notice">当前分析使用部分片单，最多5,000条；不代表完整观看历史。</p>
  <p v-if="error" class="feedback error" role="alert">{{ error }} <button @click="load">重试</button></p>
  <p v-if="loading || viewer.loading" class="feedback" role="status">正在整理你的观看偏好…</p>
  <template v-if="report">
    <div class="preference-summary"><div><span>已看作品</span><strong>{{ report.summary.completed }}<small>部</small></strong></div><div><span>有个人评分</span><strong>{{ report.summary.rated }}<small>部</small></strong></div><div><span>个人平均分</span><strong>{{ report.summary.averageRating ?? '—' }}<small>/ 10</small></strong></div><div><span>个人高分作品 · ≥8分</span><strong>{{ report.summary.highRated }}<small>部</small></strong></div></div>
    <section class="insight-panel"><p class="eyebrow">A FEW OBSERVATIONS / 片单里的线索</p><p v-for="insight in report.insights" :key="insight">{{ insight }}</p><small>数据来自 @{{ viewer.state?.profile?.username }} · {{ viewer.state?.verified ? '令牌验证读取' : '公开动画收藏' }} · 最近成功同步 {{ viewer.state?.lastSyncedAt ? new Date(viewer.state.lastSyncedAt).toLocaleString('zh-CN') : '尚未同步' }}</small></section>
    <section class="taste-panel"><div class="taste-panel-heading"><div><h2>常见标签与评分</h2><p>区分“经常看见”和“评分更高”，不把出现次数直接当作喜欢。</p></div><div class="taste-filters"><label>标签来源<select v-model="source"><option value="COMMUNITY">作品社区标签</option><option value="PERSONAL">我的个人标签</option></select></label><label>排列方式<select v-model="sort"><option value="frequency">出现次数</option><option value="rating">校正个人评分</option></select></label></div></div><p class="coverage">可用标签覆盖 {{ report.summary.tagged }} / {{ report.summary.completed }} 部已看作品（{{ report.summary.tagCoverage }}%）。从 {{ report.totalTags ?? report.tags.length }} 个有效标签中按当前方式展示前20项；点击标签查看依据。{{ report.tagSource === 'COMMUNITY' ? '每部作品仅有来源摘要中的前10个社区标签。' : '只使用你在Bangumi为收藏填写的个人标签。' }}</p><ReportChart v-if="tags.length" :items="tags.map(tag=>({id:tag.name,label:tag.name,count:tag.count,sample:tag.ratedCount,score:tag.averageRating}))" label="标签出现作品数（多标签可重叠，比例分母为已看作品）" @select="router.push(tagEvidence($event.id))"/><details v-if="tags.length"><summary>标签评分与数量明细</summary><div class="table-scroll"><table class="taste-table"><thead><tr><th>标签</th><th>出现次数 / 占已看比例</th><th>个人评分样本</th><th>个人均分</th><th>校正评分</th></tr></thead><tbody><tr v-for="tag in tags" :key="tag.name"><td><RouterLink :to="tagEvidence(tag.name)" class="tag-evidence" :aria-label="`查看${tag.name}标签的${tag.count}部已看作品`">{{ tag.name }} ↗</RouterLink></td><td><div class="tag-count"><div><i :style="{ width: `${tag.share}%` }"></i></div><span>{{ tag.count }} 部 · {{ tag.share }}%</span></div></td><td>{{ tag.ratedCount }} 部</td><td>{{ tag.averageRating ?? '未评分' }}</td><td>{{ tag.adjustedRating ?? '样本不足3部' }}</td></tr></tbody></table></div></details><div v-else class="empty-state"><h3>暂未找到可统计的标签</h3><p>可以切换标签来源，或在 Bangumi 补充个人标签后重新同步。</p></div></section>
    <div class="distribution-grid"><section class="taste-panel"><h2>个人评分分布</h2><p class="chart-note">仅已看且已评分作品；另有 {{ report.summary.unrated }} 部未评分</p><DistributionBars :items="report.ratings.map(i => ({ ...i, label: `${i.label} 分` }))" label="个人评分分布" :link-for="item => evidenceLink({ rating: item.label.split(' ')[0] })" /></section><section class="taste-panel"><h2>观看状态</h2><p class="chart-note">全部已同步动画收藏</p><DistributionBars :items="report.statuses" label="观看状态" :link-for="item => statusEvidence(item.label)" /></section><section class="taste-panel"><h2>常看的发行年份</h2><p class="chart-note">按出现次数展示前12个年份；这是发行年，不是观看年</p><DistributionBars :items="years" label="发行年份" :link-for="item => evidenceLink({ year: item.label === '未知' ? 'UNKNOWN' : item.label })" /></section><section class="taste-panel"><h2>动画形式</h2><p class="chart-note">依据来源现有标签识别，未标注时保留未知</p><DistributionBars :items="report.formats" label="动画形式" :link-for="item => evidenceLink({ format: item.label === '未标注' ? 'UNKNOWN' : item.label })" /></section></div>
    <section v-if="report.quality" class="quality-panel"><div><h2>统计覆盖与待补资料</h2><p>个人评分覆盖 {{ report.quality.ratingCoverage }}% 的已看作品。以下项目可能重叠，点击查看具体记录。</p></div><div class="quality-items"><RouterLink :to="evidenceLink({ rating: 'UNRATED' })"><strong>{{ report.summary.unrated }}</strong><span>未评分作品 ↗</span></RouterLink><RouterLink :to="evidenceLink({ missingTags: true, tagSource: report.tagSource })"><strong>{{ report.quality.missingTags }}</strong><span>缺少有效标签 ↗</span></RouterLink><RouterLink :to="evidenceLink({ year: 'UNKNOWN' })"><strong>{{ report.quality.missingYear }}</strong><span>发行年份未知 ↗</span></RouterLink><RouterLink :to="evidenceLink({ format: 'UNKNOWN' })"><strong>{{ report.quality.missingFormat }}</strong><span>形式未标注 ↗</span></RouterLink></div></section>
    <section class="favorite-section"><h2>你给过高分的故事 <small>个人评分 ≥8，最多展示12部</small><RouterLink class="all-favorites" :to="evidenceLink({ rating: 'HIGH', sort: 'rating' })">查看全部 ↗</RouterLink></h2><div v-if="report.favorites.length" class="favorites-grid"><ViewingCard v-for="item in report.favorites" :key="item.subjectId" :item="item" /></div><p v-else class="empty-state">还没有已看且个人评分达到8分的作品。</p></section>
    <ViewerReportPanel :scope="`${viewer.state?.profile?.id}|${viewer.state?.lastSyncedAt}`"/><RecommendationsPanel :scope="`${viewer.state?.profile?.id}|${viewer.state?.lastSyncedAt}`"/><details class="methodology"><summary>这些统计如何计算？</summary><ol><li v-for="item in report.methodology" :key="item">{{ item }}</li></ol></details>
  </template>
</template>
<style scoped>
.tag-evidence{color:#5b7f50;font-weight:550;display:inline-block;min-height:34px;padding:6px 0}.tag-evidence:hover{text-decoration:underline}.all-favorites{font-size:11px;color:#749564;float:right;margin-top:5px}.quality-panel{border:1px solid #dce6d1;border-radius:13px;background:#f1f5e9;padding:25px;margin:25px 0}.quality-panel h2{font-size:17px;font-weight:550;margin:0}.quality-panel p{font-size:11px;color:#8e9d80;line-height:1.9}.quality-items{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin-top:20px}.quality-items a{display:grid;gap:6px;color:#8a9c79;font-size:11px;min-height:65px}.quality-items a:hover span{text-decoration:underline}.quality-items strong{font-size:25px;font-weight:450;color:#5c7f4d}@media(max-width:650px){.quality-items{grid-template-columns:repeat(2,minmax(0,1fr))}.all-favorites{float:none;display:block;margin:10px 0}}

.preference-intro{display:flex;align-items:center;justify-content:space-between;gap:25px;padding:42px 0 25px}.preference-intro h1{font-size:clamp(27px,3.2vw,38px);font-weight:550;margin:10px 0 12px}.preference-intro h1 span{color:#8da37e}.preference-intro p{font-size:13px;color:#8b9b7f}.preference-intro>.button{font-size:11px;flex-shrink:0}.preference-empty{text-align:center;padding:70px 15px;color:#8ea47b}.preference-empty>span{font-size:50px;color:#c1d0b1}.preference-empty h2{font-size:22px;font-weight:500}.preference-empty p{font-size:13px;margin-bottom:28px}.preference-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:9px 0 24px}.preference-summary>div{padding:22px 25px;border:1px solid #e1e8d9;background:white;border-radius:12px;display:grid;gap:8px;font-size:11px;color:#93a282}.preference-summary strong{font-size:31px;font-weight:450;color:#4b6e4e;font-variant-numeric:tabular-nums}.preference-summary strong small{font-size:11px;margin-left:8px;color:#a5b396;font-weight:400}.insight-panel{padding:26px 29px;background:#edf3e5;border:1px solid #dfe8d3;border-radius:13px;margin:23px 0 27px}.insight-panel>.eyebrow{font-size:9px;letter-spacing:1.5px;margin:0 0 16px;color:#8fa57c}.insight-panel>p:not(.eyebrow){font-size:13px;line-height:1.9;color:#617e54;margin:9px 0}.insight-panel>small{display:block;margin-top:20px;color:#a0ae90;font-size:10px}.taste-panel{border:1px solid #dfe7d5;border-radius:13px;padding:25px;background:white;min-width:0}.taste-panel h2,.favorite-section h2{font-size:18px;font-weight:550;margin:0 0 8px}.taste-panel-heading{display:flex;justify-content:space-between;align-items:start;gap:20px}.taste-panel-heading p,.coverage,.chart-note{font-size:11px;color:#98a68b;line-height:1.9}.taste-filters{display:flex;gap:10px}.taste-filters label{font-size:10px;min-width:130px}.taste-filters select{font-size:11px;padding:8px 10px}.coverage{border-top:1px solid #edf0e7;padding-top:15px;margin:18px 0 10px}.taste-table{font-variant-numeric:tabular-nums}.taste-table strong{font-weight:550;color:#658356}.taste-table td{color:#8a9f78;font-size:11px}.tag-count{min-width:180px;display:flex;align-items:center;gap:12px;font-size:10px}.tag-count>div{width:75px;flex-shrink:0;border-radius:4px;background:#f0f5e9;height:6px;overflow:hidden}.tag-count i{display:block;height:100%;background:#aac095;min-width:1px;border-radius:4px}.tag-count>span{white-space:nowrap}.distribution-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:23px 0 30px}.chart-note{margin:0 0 24px}.favorite-section{margin:30px 0}.favorite-section h2 small{font-size:10px;color:#a0af8e;font-weight:400;margin-left:12px}.favorites-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:21px}.methodology{border-top:1px solid #dfe7d4;padding:20px 0 35px;font-size:12px;color:#8fa27f}.methodology summary{cursor:pointer;min-height:40px;padding:9px 0}.methodology li{font-size:11px;line-height:2;margin-bottom:7px;overflow-wrap:anywhere}@media(max-width:850px){.taste-panel-heading{flex-direction:column}.preference-summary{gap:12px}.preference-summary>div{padding:18px}}@media(max-width:650px){.preference-intro{align-items:start;flex-direction:column;padding-top:30px;gap:12px}.preference-summary{grid-template-columns:repeat(2,1fr)}.distribution-grid,.favorites-grid{grid-template-columns:1fr}.taste-panel{padding:20px}.insight-panel{padding:22px}.favorite-section h2 small{display:block;margin:8px 0}.taste-filters{width:100%}.taste-filters label{flex:1;min-width:0}.preference-intro h1{font-size:27px}}
</style>

